(function(){const incoming=[{"id":"history-course-nov11-1","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","topicOrder":8,"part":1,"cardTitle":"Тест по теме","label":"Тест по теме","title":"Тема 8. Первые Романовы · Тест по теме","period":"История России","description":"29 заданий по теме. Подсказки и разборы; изображения — по ссылкам на оригинал.","questions":[{"id":"history-nov11-1-q1","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 1","ex":"А) Так называемый «поход за зипунами» под руководством Степана Разина на Каспийское море и в Персию продолжался с 1667 по 1669 год.\n\nБ) Поляновский мирный договор между Россией и Речью Посполитой был подписан в 1634 году. Он завершил Смоленскую войну 1632-1634 годов.\n\nВ) Белоцерковский мирный договор между Речью Посполитой и казаками Богдана Хмельницкого был заключён в 1651 году после поражения казаков в Берестецкой битве.\n\nГ) Кардисский мирный договор между Россией и Швецией был подписан в 1661 году. Он подтвердил условия Столбовского мира 1617 года, сохранив за Швецией прибалтийские территории.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1651 г.","1642 г.","1634 г.","1679 г.","1667-1669 г.","1661 г."],"rows":[{"id":"row1","label":"поход «за зипунами» на Каспий","answer":"1667-1669 г."},{"id":"row2","label":"Поляновский мирный договор","answer":"1634 г."},{"id":"row3","label":"Белоцерковский мир","answer":"1651 г."},{"id":"row4","label":"Кардисский мир","answer":"1661 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q2","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 2","ex":"А) В 1679 году правительство царя Фёдора Алексеевича заменило посошное обложение подворным налогом (с каждого двора). Это упростило систему налогообложения и увеличило налоговые поступления в казну.\n\nБ) В 1648 году Семён Иванович Дежнёв возглавил морской поход вокруг Чукотского полуострова. В ходе экспедиции был открыт пролив между Азией и Северной Америкой (позднее названный Беринговым проливом).\n\nВ) Новоторговый устав 1667 года был разработан при царе Алексее Михайловиче под руководством боярина А. Л. Ордина-Нащокина. Устав регулировал внутреннюю и внешнюю торговлю, предоставлял льготы русским купцам, ограничивал иностранное торговое влияние и способствовал развитию всероссийского рынка.\n\nГ) Приказ Тайных дел был создан царём Алексеем Михайловичем в 1654 году для контроля за деятельностью государственных учреждений.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1667 г.","1650 г.","1648 г.","1669 г.","1654 г.","1679 г."],"rows":[{"id":"row1","label":"введение подворного обложения","answer":"1679 г."},{"id":"row2","label":"начало экспедиции Семёна Дежнёва","answer":"1648 г."},{"id":"row3","label":"принятие Новоторгового устава","answer":"1667 г."},{"id":"row4","label":"создание приказа Тайных дел","answer":"1654 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q3","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 3","ex":"А) Переяславская рада — собрание представителей запорожского казачества во главе с гетманом Богданом Хмельницким, состоявшееся в январе 1654 года.\n\nБ) Бахчисарайский мирный договор между Россией и Османской империей был подписан в 1681 году.\n\nВ) Крупные городские восстания в Новгороде и Пскове, вызванные резким повышением цен на хлеб и злоупотреблениями властей, произошли в 1650 году.\n\nГ) Соляной бунт — массовое народное восстание в Москве в июне 1648 года, вызванное недовольством налоговой политикой правительства Бориса Морозова, в частности введением высокого налога на соль.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1651 г.","1650 г.","1654 г.","1648 г.","1683 г.","1681 г."],"rows":[{"id":"row1","label":"Переяславская рада","answer":"1654 г."},{"id":"row2","label":"Бахчисарайский мирный договор","answer":"1681 г."},{"id":"row3","label":"восстания в Новгороде и Пскове","answer":"1650 г."},{"id":"row4","label":"Соляной бунт","answer":"1648 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q4","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 4","ex":"А) После подавления восстания 1670–1671 годов Степан Разин был выдан царским властям его соратниками в Кагальницком городке в 1671 году.\n\nБ) В 1639 году отряд казаков под командованием Ивана Юрьевича Москвитина вышел к Охотскому морю. Это было одно из первых русских путешествий к Тихому океану, в ходе которого были исследованы побережье и устье реки Ульи.\n\nВ) Медный бунт произошёл в Москве в 1662 году. Причиной стали массовый выпуск медных денег (вместо серебряных), их обесценивание и рост цен.\n\nГ) Переяславская рада 1654 года - собрание представителей украинского казачества и жителей, на котором было принято решение о переходе Войска Запорожского под протекторат России.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1639 г.","1654 г.","1649 г.","1671 г.","1679 г.","1662 г."],"rows":[{"id":"row1","label":"казнь Степана Разина в Москве","answer":"1671 г."},{"id":"row2","label":"экспедиция Ивана Москвитина","answer":"1639 г."},{"id":"row3","label":"Медный бунт","answer":"1662 г."},{"id":"row4","label":"Переяславская рада","answer":"1654 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q5","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 5","ex":"А) Андрусовское перемирие между Россией и Речью Посполитой было подписано в 1667 году. Оно завершило русско-польскую войну 1654-1667 годов и закрепило переход Левобережной Украины и Киева к России.\n\nБ) Экспедиция Ерофея Павловича Хабарова в Приамурье проходила с 1649 по 1653 год. В ходе этих походов были исследованы земли по реке Амур и составлены их подробные чертежи.\n\nВ) Соловецкое восстание продолжалось с 1668 по 1676 год. Это было вооружённое сопротивление монахов Соловецкого монастыря церковным реформам патриарха Никона.\n\nГ) Поход донского казака Василия Уса с отрядом на Тулу и другие центральные уезды состоялся в 1666 году.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1649–1653 гг.","1666 г.","1615 г.","1667 г.","1678 г.","1668-1676 г."],"rows":[{"id":"row1","label":"Андрусовское перемирие","answer":"1667 г."},{"id":"row2","label":"экспедиция Ерофея Хабарова","answer":"1649–1653 гг."},{"id":"row3","label":"Соловецкое восстание","answer":"1668-1676 г."},{"id":"row4","label":"бунт Василия Уса","answer":"1666 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q6","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 6","ex":"А) Соляной бунт произошёл в Москве в июне 1648 года. Поводом стало введение высокого налога на соль. Бунт ускорил созыв Земского собора и принятие Соборного уложения.\n\nБ) Царь Фёдор III Алексеевич умер в 1682 году, не оставив наследников. Его смерть вызвала стрелецкий бунт, в результате которого на престол были возведены сразу два царя - Иван V и Пётр I, а регентшей стала царевна Софья.\n\nВ) В 1650 году в Пскове и Новгороде вспыхнули восстания («хлебные бунты») из-за роста цен на хлеб, вызванного поставками зерна в Швецию.\n\nГ) 21 февраля 1613 года Земский собор избрал на царство 16-летнего Михаила Фёдоровича Романова, положив начало династии Романовых, правившей Россией более 300 лет.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1650 г.","1682 г.","1617 г.","1655 г.","1648 г.","1613 г."],"rows":[{"id":"row1","label":"Соляной бунт в Москве","answer":"1648 г."},{"id":"row2","label":"смерть Фёдора Алексеевича","answer":"1682 г."},{"id":"row3","label":"восстания в Новгороде и Пскове","answer":"1650 г."},{"id":"row4","label":"избрание Михаила Романова царём","answer":"1613 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q7","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 7","ex":"1) Большой Московский церковный собор - 1666-1667 гг.\n\n2) Смоленская война между Россией и Речью Посполитой - 1632–1634 гг.\n\n3) провозглашение Англии республикой - 1649 г.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"Большой Московский церковный собор"},{"id":"2","label":"Смоленская война между Россией и Речью Посполитой"},{"id":"3","label":"провозглашение Англии республикой"}],"answer":["2","3","1"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-1-q8","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 8","ex":"1) введение Новоторгового устава - 1667 г.\n\n2) «Соляной бунт» 1648 г.\n\n3) начало Английской буржуазной революции - 1640 г.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"введение Новоторгового устава"},{"id":"2","label":"«Соляной бунт»"},{"id":"3","label":"начало Английской буржуазной революции"}],"answer":["3","2","1"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-1-q9","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 9","ex":"1) Вестфальский мир - 1648 г.\n\n2) Соловецкое восстание - 1668-1676 гг.\n\n3) Переяславская рада - 1654 г.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"Вестфальский мир"},{"id":"2","label":"Соловецкое восстание"},{"id":"3","label":"Переяславская рада"}],"answer":["1","3","2"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-1-q10","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 10","ex":"1) начало экспедиции Семена Дежнева - 1648 г.\n\n2) принятие английским парламентом «Великой ремонстрации» - 1641 г.\n\n3) утверждение Соборного Уложения - 1649 г.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"начало экспедиции Семена Дежнева"},{"id":"2","label":"принятие английским парламентом «Великой ремонстрации»"},{"id":"3","label":"утверждение Соборного Уложения"}],"answer":["2","1","3"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-1-q11","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 11","ex":"А) Новоторговый устав 1667 года, разработанный А.Л. Ординым-Нащокиным, является ярким примером протекционистской политики.\n\nБ) Берестецкая битва — крупное сражение между войсками Богдана Хмельницкого и армией Речи Посполитой, закончившееся поражением казаков.\n\nВ) Экспедиция Василия Пояркова была первой русской экспедицией в Приамурье. Поярков исследовал бассейн реки Амур и собрал ценные сведения о природных богатствах региона.\n\nГ) Осада Смоленска русскими войсками под командованием воеводы Михаила Шеина была центральным событием Смоленской войны.","type":"match","q":"Установите соответствие между процессами (явлениями, событиями) и фактами, относящимися к этим процессам (явлениям, событиям): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Берестецкая битва","экспедиция Василия Пояркова","осада Смоленска","издание Новоторгового устава","казнь Плещеева","создание приказа Тайных дел"],"rows":[{"id":"row1","label":"политика протекционизма Русского царства в XVII в.","answer":"издание Новоторгового устава"},{"id":"row2","label":"восстание запорожских казаков под командованием Богдана Хмельницкого","answer":"Берестецкая битва"},{"id":"row3","label":"освоение юго-восточной Сибири и Дальнего Востока русскими первопроходцами","answer":"экспедиция Василия Пояркова"},{"id":"row4","label":"Смоленская война","answer":"осада Смоленска"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q12","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 12","ex":"А) Соборное уложение 1649 года окончательно оформило крепостное право: был введён бессрочный сыск беглых крестьян, крестьяне прикреплялись к земле и помещику.\n\nБ) Церковная реформа патриарха Никона включала исправление богослужебных книг по греческим образцам, введение троеперстия, изменение обрядов.\n\nВ) Поход «за зипунами» - поход казаков Степана Разина на Волгу и Каспий, ставший прологом к крупному восстанию 1670–1671 годов.\n\nГ) В 1630-х годах при царе Михаиле Фёдоровиче началось создание полков нового (иноземного) строя, организованных по западноевропейскому образцу.","type":"match","q":"Установите соответствие между процессами (явлениями, событиями) и фактами, относящимися к этим процессам (явлениям, событиям): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["создание полков нового строя","принятие Соборного уложения","поход «за зипунами»","заключение Андрусовского перемирия","исправление церковных книг и обрядов","экспедиция Ерофея Хабарова"],"rows":[{"id":"row1","label":"укрепление крепостного права в XVII в.","answer":"принятие Соборного уложения"},{"id":"row2","label":"реформа патриарха Никона","answer":"исправление церковных книг и обрядов"},{"id":"row3","label":"восстание под руководством Степана Разина","answer":"поход «за зипунами»"},{"id":"row4","label":"военная реформа Михаила Фёдоровича","answer":"создание полков нового строя"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q13","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 13","ex":"А — Москва; Б — 1670-е гг. (казнь Разина в 1671 г.); В — Поляново; Г — 1634 г.; Д — переход Левобережной Украины и Смоленской земли по Андрусовскому перемирию 1667 г.; Е — Азов, османская крепость, взятая донскими казаками в 1637 г.","type":"match","q":"Заполните пустые ячейки таблицы, используя приведённый ниже список пропущенных элементов: для каждого пропуска, обозначенного буквой, выберите номер нужного элемента.","bodyHtml":"<table style=\"min-width: 300px;\"><colgroup><col style=\"min-width: 100px;\"><col style=\"min-width: 100px;\"><col style=\"min-width: 100px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Географический объект</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>Событие (явление, процесс)</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>Время, когда произошло событие (явление, процесс)</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (А)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Казнь Степана Разина</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Б)</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (В)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Заключение русско-польского договора, по условиям которого польский король Владислав отказался от претензий на трон русского царя</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Г)</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Андрусово</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Д)</p></td><td colspan=\"1\" rowspan=\"1\"><p>1667 г.</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Е)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Взятие крепости донскими казаками</p></td><td colspan=\"1\" rowspan=\"1\"><p>1637 г.</p></td></tr></tbody></table>","options":["Якутск","Заключение русско-польского договора, по условиям которого к России переходили Левобережная Украина и Смоленская земля.","1670-е гг.","1634 г.","Поляново","Заключение русско-шведского мирного договора, по условиям которого к Швеции переходили Ям, Ивангород, Копорье, Орешек и Корела.","Москва.","Азов.","1654 г."],"rows":[{"id":"row1","label":"Пропуск А","answer":"Москва."},{"id":"row2","label":"Пропуск Б","answer":"1670-е гг."},{"id":"row3","label":"Пропуск В","answer":"Поляново"},{"id":"row4","label":"Пропуск Г","answer":"1634 г."},{"id":"row5","label":"Пропуск Д","answer":"Заключение русско-польского договора, по условиям которого к России переходили Левобережная Украина и Смоленская земля."},{"id":"row6","label":"Пропуск Е","answer":"Азов."}],"hint":"Для каждого буквенного пропуска определите, что требуется: место, событие или дата."},{"id":"history-nov11-1-q14","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 14","ex":"1) Во время Медного бунта (1662 года) восставшие москвичи двинулись в село Коломенское, где находился царь Алексей Михайлович. Царь вступил с ними в переговоры, обещая разобраться, но затем вызвал войска и подавил бунт.\n\n2) В октябре 1670 года под Симбирском произошло решающее сражение между войсками Степана Разина и правительственными войсками. Разин был разбит и бежал на Дон.\n\n3) Столбовский мирный договор между Россией и Швецией был подписан в 1617 году в деревне Столбово. Он завершил русско-шведскую войну.\n\n4) Соловецкое восстание - сопротивление монахов Соловецкого монастыря церковным реформам патриарха Никона. Монастырь отказался принимать новые богослужебные книги и обряды, что привело к его многолетней осаде правительственными войсками.","type":"match","q":"Заполните пустые ячейки таблицы, используя приведённый ниже список пропущенных элементов: для каждого пропуска, обозначенного буквой, выберите номер нужного элемента.","bodyHtml":"<table style=\"min-width: 300px;\"><colgroup><col style=\"min-width: 100px;\"><col style=\"min-width: 100px;\"><col style=\"min-width: 100px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Географический объект</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>Событие (явление, процесс)</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>Время, когда произошло событие (явление, процесс)</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>село Коломенское</p></td><td colspan=\"1\" rowspan=\"1\"><p>_______________(а)</p></td><td colspan=\"1\" rowspan=\"1\"><p>1662 г.</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_______________(б)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Победа царских войск над бунтовщиками Степана Разина</p></td><td colspan=\"1\" rowspan=\"1\"><p>_______________(в)</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Столбово</p></td><td colspan=\"1\" rowspan=\"1\"><p>_______________(г)</p></td><td colspan=\"1\" rowspan=\"1\"><p>1617 г.</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_______________(д)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Начало крупного старообрядческого восстания</p></td><td colspan=\"1\" rowspan=\"1\"><p>_______________(е)</p></td></tr></tbody></table>","options":["Симбирск.","Переговоры царя Алексея Михайловича с бунтовщиками во время Медного бунта.","Тула.","Соловецкий монастырь.","Основание первой крупной железоделательной мануфактуры.","1670 г.","1668 г.","Заключение мирного договора с Швецией.","1648 г."],"rows":[{"id":"row1","label":"Пропуск А","answer":"Переговоры царя Алексея Михайловича с бунтовщиками во время Медного бунта."},{"id":"row2","label":"Пропуск Б","answer":"Симбирск."},{"id":"row3","label":"Пропуск В","answer":"1670 г."},{"id":"row4","label":"Пропуск Г","answer":"Заключение мирного договора с Швецией."},{"id":"row5","label":"Пропуск Д","answer":"Соловецкий монастырь."},{"id":"row6","label":"Пропуск Е","answer":"1668 г."}],"hint":"Для каждого буквенного пропуска определите, что требуется: место, событие или дата."},{"id":"history-nov11-1-q15","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 15","ex":"А) Новоиерусалимский (Воскресенский) монастырь на реке Истре был основан патриархом Никоном.\n\nБ) Василий Ус был одним из ближайших сподвижников Степана Разина и активным участником восстания.\n\nВ) Новоторговый устав 1667 года был разработан под руководством государственного деятеля Афанасия Лаврентьевича Ордина-Нащокина.\n\nГ) Протопоп Аввакум стал главным идеологом и духовным лидером старообрядчества, непримиримым противником церковной реформы патриарха Никона.","type":"match","q":"Установите соответствие между событиями (явлениями, процессами) и участниками этих событий (явлений, процессов): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Василий Ус","Аввакум","патриарх Никон","патриарх Филарет","Афанасий Ордин-Нащокин","Борис Морозов"],"rows":[{"id":"row1","label":"основание Новоиерусалимского монастыря","answer":"патриарх Никон"},{"id":"row2","label":"восстание под предводительством Степана Разина","answer":"Василий Ус"},{"id":"row3","label":"разработка Новоторгового устава","answer":"Афанасий Ордин-Нащокин"},{"id":"row4","label":"становление старообрядческого движения в России","answer":"Аввакум"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q16","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 16","ex":"А) Деулинское перемирие с Речью Посполитой было заключено в 1618 году при царе Михаиле Фёдоровиче Романове.\n\nБ) В 1639 году отряд казаков под командованием Ивана Юрьевича Москвитина вышел к Охотскому морю. Это было одно из первых русских путешествий к Тихому океану, положившее начало освоению Дальнего Востока.\n\nВ) Князь Никита Иванович Одоевский возглавлял комиссию по подготовке Соборного уложения 1649 года - первого печатного свода законов Русского царства.\n\nГ) Зборовский договор был заключён в 1649 году между гетманом Богданом Хмельницким и польским королём Яном Казимиром.","type":"match","q":"Установите соответствие между событиями (явлениями, процессами) и участниками этих событий (явлений, процессов): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Иван Москвитин","Богдан Хмельницкий","Михаил Фёдорович","Владимир Атласов","Никита Одоевский","Симеон Полоцкий"],"rows":[{"id":"row1","label":"заключение Деулинского перемирия","answer":"Михаил Фёдорович"},{"id":"row2","label":"экспедиция к Охотскому морю в 1639 г.","answer":"Иван Москвитин"},{"id":"row3","label":"разработка Соборного уложения","answer":"Никита Одоевский"},{"id":"row4","label":"заключение Зборовского договора","answer":"Богдан Хмельницкий"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q17","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 17","ex":"А) Богдан Хмельницкий был инициатором и участником Переяславской рады 1654 года, на которой было принято решение о переходе украинских земель под власть русского царя.\n\nБ) Владимир Васильевич Атласов возглавил экспедицию на Камчатку, в результате которой был составлен первый подробный описания полуострова и начато его присоединение к России.\n\nВ) Михаил Борисович Шеин командовал русскими войсками во время Смоленской войны 1632-1634 годов. После неудачной осады Смоленска и капитуляции армии был обвинён в измене и казнён.\n\nГ) Царь Фёдор Алексеевич в 1682 году подписал решение о полной отмене местничества — системы распределения государственных должностей по знатности рода.","type":"match","q":"Установите соответствие между событиями (явлениями, процессами) и участниками этих событий (явлений, процессов): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Владимир Атласов","Федор Алексеевич","Михаил Шеин","Андрей Курбский","Богдан Хмельницкий","Стефан Баторий"],"rows":[{"id":"row1","label":"Переяславская рада","answer":"Богдан Хмельницкий"},{"id":"row2","label":"освоение Камчатки","answer":"Владимир Атласов"},{"id":"row3","label":"Смоленская война","answer":"Михаил Шеин"},{"id":"row4","label":"отмена местничества","answer":"Федор Алексеевич"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-1-q18","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 18","ex":"1) ДА, верно. В тексте описаны события одного из восстаний Бунташного века. Медный бунт 1662 года в Москве, вызванный финансовой реформой и выпуском обесценившихся медных денег, является характерным восстанием \"Бунташного века\" (XVII в.).\n\n2) НЕТ, неверно. Во время Медного бунта 1662 года толпа требовала выдачи боярина И.Д. Милославского и других, обвиненных в злоупотреблениях.\n\n3) ДА, верно. Медный бунт произошел в 1662 году в правление царя Алексея Михайловича (1645-1676 гг.).\n\n4) ДА, верно. Хотя сам бунт был подавлен, в 1663 году правительство было вынуждено отменить медные деньги и вернуться к серебряной монете.\n\n5) НЕТ, неверно. Соборное уложение было принято в 1649 году после Соляного бунта.\n\n6) НЕТ, неверно. Медный бунт произошел в 1662 году, а восстание Степана Разина происходило в 1670–1671 годах; поход «за зипунами» — в 1667–1669 годах.","type":"multi","q":"Прочтите отрывок из исторического источника.\n\n«Рано утром, когда я обучал полк на поле у Новоспасского монастыря, к нам явился полковник Крофорд, сообщил, что в городе великое смятение, и дал приказ выступать к Таганским воротам. Я осведомился, где царь, и узнав, что он в Коломенском, советовал идти туда, на что полковник никак не соглашался и послал одного русского лейтенанта разведать, в чём дело…\n\nМятежники толпою вышли из Серпуховских ворот. Их было около 4 или 5 тысяч, без оружия, лишь у некоторых имелись дубины и палки. Они притязали на возмещение за медные деньги, соль и многое другое. С сею целью в разных местах города были расклеены листы, а один стряпчий перед Земским двором читал лист, содержащий их жалобы, имена некоторых особ, коих они мнили виновными в злоупотреблениях, и призыв ко всем идти к царю и добиваться возмещения, а также голов дурных советников».\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"В тексте описаны события одного из восстаний Бунташного века."},{"id":"2","label":"К числу обвиняемых в злоупотреблениях, выдачи голов которых требовали восставшие, были Л. Плещеев, П. Траханиотов и Б. Морозов."},{"id":"3","label":"Автор упоминает о царе Алексее Михайловиче."},{"id":"4","label":"По итогам восстания медные монеты начали изыматься из оборота."},{"id":"5","label":"После разгрома данного восстания было принято новое Соборное уложение."},{"id":"6","label":"Одновременно с бунтом, упоминаемым в документе, на юге страны началось восстание под руководством С. Разина."}],"answer":["1","3","4"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-1-q20","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 20","ex":"1) НЕТ, неверно. В отрывке описывается Азовское сидение (1637-1642 гг.) — взятие и оборона донскими казаками турецкой крепости Азов.\n\n2) ДА, верно. После взятия казаками Азова в 1637 году и последовавшей их просьбы к царю Михаилу Фёдоровичу принять крепость «под свою руку», в 1642 году был созван Земский собор, который постановил, что Россия не готова к войне с Османской империей.\n\n3) НЕТ, неверно. Боярин Борис Морозов был фактическим правителем в начале царствования Алексея Михайловича. Монарх, упомянутый в отрывке — Михаил Фёдорович (правил в 1613-1645 гг.)\n\n4) ДА, верно. При Михаиле Фёдоровиче действительно началось создание полков нового строя по европейскому образцу.\n\n5) НЕТ, неверно. Это характерные причины восстания Степана Разина.\n\n6) ДА, верно. Текст представляет собой фрагмент ответа донских казаков турецкому султану, который предлагал им перейти на свою службу после их взятия Азова.","type":"multi","q":"Прочтите отрывок из повести.\n\n«А мы у вас взяли Азов-город по своей казачьей воле, а не по государеву повелению, ради казачьих зипунов своих и за ваши высокомерные лютые помыслы. За то на нас, холопов своих дальних, государь крепко обижен. Боимся от него, государя царя, за то взятие… себе наказания смертного. А государь наш — великий, пресветлый и праведный царь и великий князь Михаил Фёдорович, всея Руси самодержец, многих государств и орд государь и обладатель… Довольно наш государь богат от Бога подданными и царскими данями и без вашего богатства. А если бы на то было его государево повеление, если б пожелал он только, великий государь, городам вашим разорения за ваше к нему, государю, непослушание… то собралось бы тут его государевых людей русских с одной лишь Украины многое множество! …А то бы не укрылся ваш Ибрагим, царь турецкий… Не защитило бы его, царя турецкого, от руки той государевой, от десницы высокой его и море синее… Вы же нас призываете речью царя турецкого служить ему, царю турецкому, и сулите нам от него честь великую и богатство многое. А мы, люди Божии, холопы государя царя Московского. Как же можем служить царю турецкому!»\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите в ответ цифры, под которыми они указаны.","options":[{"id":"1","label":"В отрывке речь идет о «походе за зипунами» Степана Разина."},{"id":"2","label":"Одним из следствий описанного в отрывке события был отказ Земского собора вступать в войну с Турцией."},{"id":"3","label":"В первые годы царствования монарха, упомянутого в отрывке, властью фактически распоряжался боярин Б. И. Морозов."},{"id":"4","label":"В период царствования монарха, упомянутого в отрывке, были созданы полки нового строя."},{"id":"5","label":"Причиной осады города, описываемое в отрывке был рост налогов, вызванный войнами и бегство крестьян от крепостничества в казачьи области на Дону."},{"id":"6","label":"Авторы послания – донские казаки."}],"answer":["2","4","6"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-1-q21","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 21","ex":"1) НЕТ, неверно. В тексте упоминается царь Алексей Михайлович (1645–1676). Речь идёт о событиях, связанных с избранием Никона патриархом в 1652 году. Михаил Фёдорович умер в 1645 году.\n\n2) ДА, верно. Текст представляет собой отрывок из «Жития протопопа Аввакума» (описание начала церковной реформы).\n\n3) НЕТ, неверно. Патриарх Иов был главой церкви в 1589–1605 годах, а описываемые события относятся к 1652–1653 годам.\n\n4) ДА, верно. Никон, упоминаемый в тексте, был инициатором и главным проводником церковной реформы 1650–1660-х годов (исправление книг по греческим образцам, унификация обрядов).\n\n5) ДА, верно. Автор (Аввакум) называет Никона «лисом», говорит о его «кознях» и «яде», что свидетельствует о негативном отношении к его действиям.\n\n6) НЕТ, неверно. «Житие протопопа Аввакума» было написано в XVII веке.","type":"multi","q":"Прочтите отрывок из исторического источника.\n\n«Стефан духовник, моля бога и постяся седмицу с братьею, - и я с ними тут же, — о патриархе, да же даст бог пастыря ко спасению душ наших, и с митрополитом казанским Корнилием, написав челобитную за руками, подали царю и царице - о духовнике Стефане, чтоб ему быть в патриархах. Он же не восхотел сам и указал на Никона митрополита. Царь ево и послушал, и пишет к нему послание навстречу: преосвященному митрополиту Никону новгороцкому и великолуцкому и всея Русии радоватися, и прочая. Егда ж приехал, с нами яко лис: челом да здорово. Ведает, что быть ему в патриархах, и чтобы откуля помешка какова не учинилась. Много о тех кознях говорить! Егда поставили патриархом, так друзей не стал и в крестовую пускать. А се и яд отрыгнул; в пост великой прислал памят к Казанской к Неронову Ивану... В памети Никон пишет: „Год и число. По преданию святых апостол и святых отец, не подобает во церкви метания творити на колену, но в пояс бы вам творити поклоны, еще же и трема персты бы есте крестились\". Мы же задумалися, сошедшеся между собою; видим, яко зима хощет быти; сердце озябло, и ноги задрожали».\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите цифры.","options":[{"id":"1","label":"Царём, который упоминается в отрывке, является Михаил Фёдорович."},{"id":"2","label":"Автор произведения - протопоп Аввакум."},{"id":"3","label":"Современником событий, описанных в документе, был патриарх Иов."},{"id":"4","label":"В документе речь идёт об инициаторе церковной реформы."},{"id":"5","label":"Автор с осуждением относится к действиям Никона."},{"id":"6","label":"Произведение было написано в XVI веке."}],"answer":["2","4","5"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-1-q22","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 22","ex":"1) ДА, верно. Документ относится к периоду правления Алексея Михайловича (1645–1676 гг.). Его правление действительно приходится на «Бунташный век» (XVII в.), отмеченный многочисленными народными восстаниями.\n\n2) ДА, верно. Пропущенное имя — Богдан Хмельницкий. Он был современником дипломата А.Л. Ордина-Нащокина.\n\n3) НЕТ, неверно. «Союз благоденствия» — тайная организация декабристов, созданная в 1818 году (XIX в.). События же документа относятся к XVII в.\n\n4) НЕТ, неверно. «Великим государем» в документе назван Алексей Михайлович, который был вторым царём из династии Романовых после своего отца Михаила Фёдоровича.\n\n5) ДА, верно. Текст прямо указывает, что польский король Ян Казимир «тое своей присяги не здержал», нарушив обязательства по защите православной веры, что, согласно документу, освобождает его подданных от верности.\n\n6) НЕТ, неверно. Эстляндия вошла в состав России только после Северной войны по Ништадтскому миру 1721 года, то есть почти через 70 лет после описываемых событий.","type":"multi","q":"Прочтите отрывок из исторического источника.\n\n«А великий государь его царское величество для православные християнские веры Яну Казимеру королю такую поступку учинит: тем людем, которые в его государском имянованье в прописках объявились, те их вины велит им отдать. и Ян Казимер король и паны рада и то дело поставили ни во что и в миру с черкасы отказали. Да и потому доведетца их принять: в присяге Яна Казимера короля написано, что ему в вере християнской остерегати и защищати, и никакими мерами для веры самому не теснити, и никого на то не попушати. А будет он тое своей присяги не здержит, и он подданных своих от всякие верности и послушанья чинит свободными. И он, Ян Казимер, тое своей присяги не здержал, и на православную християнскую веру гречаскаго закона востал, и церкви божии многие разорил, а выных унею учинил. И чтоб их не отпустить в подданство турскому салтану или крымскому хану, потому что они стали ныне присягою королевскою вольные люди. И по тому по всему приговорили: гетмана [...] и все Войско Запорожское с городами и с землями принять».\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Эпоху правления монарха, к периоду правления которого относится создание данного документа, часто называют «Бунташным веком»."},{"id":"2","label":"Гетман, чье имя пропущено в тексте, был современником А.Л. Ордина-Нащокина."},{"id":"3","label":"В том же веке, к которому относятся описанные в тексте события, был создан «Союз благоденствия»."},{"id":"4","label":"«Великий государь», упомянутый в тексте, был первым представителем царской династии Романовых."},{"id":"5","label":"Документ обвиняет польского правителя в несоблюдении договоренностей."},{"id":"6","label":"К моменту создания документа в Россию входила Эстляндия."}],"answer":["1","2","5"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-1-q23","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 23","ex":"Внимательно смотрим на карту: видим, что в состав России уже входит Киев, Левобережная Украина и Смоленск (присоединены в 1667 г.), но еще не входят Рига, Ревель, Выборг (присоединены Петром I в рамках Северной войны 1700-1721 гг.) Поэтому граница может относиться только к концу XVII в.","type":"short","q":"Закончите предложение: «Границы Европейской части России обозначены на схеме на конец ____________ в.» Ответ запишите словом.","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/i7h1ovfbGpfH_8-1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["семнадцатого","семнадцатый"],"answer":"семнадцатого"},{"id":"history-nov11-1-q24","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 24","ex":"Цифрой «2» отмечен Архангельск. Ориентиры — Белое море, река Северная Двина.","type":"short","q":"Укажите название города-порта, обозначенного на схеме цифрой «2».","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/amA99X2NoM4i_8-1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["архангельск"],"answer":"архангельск"},{"id":"history-nov11-1-q25","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 25","ex":"Уфа находится на Белой реке (смотрим на карту).","type":"short","q":"Прочтите текст о событиях, отражённых на схеме, и, используя схему, укажите название реки, пропущенное («____________________») в этом тексте.\n\n«История Уфы начинается с 1574 (по другим данным — с 1586) года со строительства Уфимского кремля. Основателем крепости является воевода Иван Нагой. В 1586 году Уфа получает статус города и становится административным центром Уфимского уезда. С появлением Уфимского уезда в крае была учреждена воеводческая форма управления. По свидетельству историков, первым воеводой стал присланный Москвой Михаил Нагой. Воевода возглавлял главное административное учреждение города — Уфимскую приказную избу. Ему подчинялось гарнизонное войско в 150—200 стрельцов. С постройкой городских стен и появлением посада (торгово-промышленной части, примыкавшей вплотную к крепости), находившийся в центре острог стал называться кремлём. Кремль был обнесён частоколом из брёвен общей длиной 440 метров, над южной и северной его частями возвышались дубовые башни.\n\nГород Уфа расположен на берегу реки __________. Башкиры называют эту реку также Ак-Идель (Агидель)».","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/09ve5MSqeLD9_8-1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["белая","белой"],"answer":"белая"},{"id":"history-nov11-1-q26","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 26","ex":"1) ДА, верно. Под цифрой «1» отмечена Тула, где в 1630-х гг. была открыта первая крупная железоделательная мануфактура.\n\n2) НЕТ, неверно. На карте заштрихованы северные районы России, специализацией которых была добыча пушнины.\n\n3) ДА, верно. Монастырь, о котором идет речь в суждении — Соловецкий. Соловецкое восстание 1668-1676 гг. — крупнейший бунт, вызванный церковным расколом середины XVII в.\n\n4) ДА, верно. Макарьевская ярмарка отмечена цифрой «4». Ориентиры — Волга, близость Нижнего Новгорода и Казани.\n\n5) ДА, верно. Значок центра полотняного производства (см. легенду карты) стоит рядом с Казанью.\n\n6) НЕТ, неверно. Внутренние таможенные пошлины были отменены Елизаветой Петровной в 1750-х гг.","type":"multi","q":"Какие суждения, относящиеся к схеме, являются верными? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Цифрой «1» на схеме обозначен город, в непосредственной близости от которого были построены первые в России железоделательные заводы."},{"id":"2","label":"На схеме заштрихованы районы, специализировавшиеся на производстве хлеба."},{"id":"3","label":"На схеме указан монастырь, где произошло крупнейшее восстание против церковной реформы, длившееся около восьми лет."},{"id":"4","label":"Одна из крупнейших ярмарок России – Макарьевская – обозначена на схеме цифрой «4»."},{"id":"5","label":"Город Казань в период, отраженный на схеме, являлся одним из центров полотняного производства."},{"id":"6","label":"Развитию хозяйства России в столетии, к которому относится историческая ситуация, обозначенная на схеме, способствовала отмена внутренних таможенных пошлин."}],"answer":["1","3","4","5"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/cb0swmbURcNf_8-1.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>"},{"id":"history-nov11-1-q27","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 27","ex":"На карте отражены два события — грабительский набег Степана Разина и его «поход за зипунами» 1667-1669 гг., и восстание Степана Разина 1670-1671 гг.","type":"short","q":"Заполните пропуск в предложении (укажите век). «События, обозначенные на схеме стрелками, произошли в _________веке». Ответ запишите словом (словосочетанием).","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/8BCpVxSuR5xO_8-2.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["семнадцатом","семнадцатый"],"answer":"семнадцатом"},{"id":"history-nov11-1-q28","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 28","ex":"Город под цифрой «2» — Симбирск, где Разин потерпел решающее поражение.","type":"short","q":"Укажите название города, отмеченного цифрой «2».","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/HAF8ztSIAgl4_8-2.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["симбирск"],"answer":"симбирск"},{"id":"history-nov11-1-q29","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 29","ex":"В устье Яика располагается город Гурьев (см. карту).","type":"short","q":"Прочтите текст о событиях, отражённых на схеме, и, используя схему, укажите название населенного пункта, пропущенное («____________________») в этом тексте.\n\n«В мае по выходе с Дона на Волгу бунтовщик из-под Саратова направил в ____________, находившийся в устье Яика, гонцов к казакам с просьбой идти к нему на соединение. А второго июня этого же года из Астраханской приказной палаты была отправлена Наказная память стрелецкому голове Ивану Яцыну об усилении обороны ____________ и преграждения восставшим пути в море. Но уже в июле в устье Яика вождь восстания разгромил отряд стрельцов во главе с Б. Северовым, посланным из Астрахани, и подошел к ____________, имея 35 стругов и «тысячи полторы и больше» присоединившихся к ним «работных людей» и стрельцов...»","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/k78akJbEUG02_8-2.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["гурьев","гурьева","гурьеву"],"answer":"гурьев"},{"id":"history-nov11-1-q30","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/99862fe3-3423-4f89-b208-2f6ba384dd7e","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 30","ex":"1) ДА, верно. Цифрой «1» отмечены низовья Дона — район проживания донского казачества в XVII в.\n\n2) НЕТ, неверно. В движении Степана Разина помимо крестьян участвовали другие сословия (казаки).\n\n3) ДА, верно. Степан Разин был казнен на Болотной площади в Москве.\n\n4) ДА, верно. Царицын был взят восставшими в самом начале мятежа.\n\n5) НЕТ, неверно. Разин не выдавал себя за чудом выжившего монарха, такое суждение было бы верным для Емельяна Пугачева, предводителя восстания 1773-1775 гг.\n\n6) НЕТ, неверно. Район восстания обозначен точечным пунктиром, город Курск находится за рамками этой области.","type":"multi","q":"Какие суждения, относящиеся к схеме, являются верными? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Цифрой «1» на схеме обозначен район проживания донских казаков."},{"id":"2","label":"В движении, обозначенном на схеме стрелками, участвовали только крестьяне."},{"id":"3","label":"Предводитель восстания был казнен в Москве."},{"id":"4","label":"Город Царицын был взят восставшими."},{"id":"5","label":"Руководитель движения выдавал себя за «чудом спасшегося императора»."},{"id":"6","label":"Город Курск находился в районе восстания, события которого отражены на карте."}],"answer":["1","3","4"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/2Hv9coCXKziH_8-2.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>"}]},{"id":"history-course-nov11-2","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","topicOrder":8,"part":2,"cardTitle":"Письменная практика","label":"Письменная практика","title":"Тема 8. Первые Романовы · Письменная практика","period":"История России","description":"5 заданий по теме. Подсказки и разборы; изображения — по ссылкам на оригинал.","questions":[{"id":"history-nov11-2-q1","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/ce54faa4-2826-4c28-be4e-d6de0beb23c6","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 1","ex":"1) монарх: Алексей Михайлович;\n\n2) объяснение: исходя из надписи на марке, можно сказать, что она посвящена 300-летию открытия пролива между Азией и Америкой. Также виден год издания марки - 1948-й. Так, проведя математическое вычисление (1948 - 300 = 1648) получаем 1648 г. Таким образом, известно что с 1645 г. российским монархом был Алексей Михайлович, при котором и произошла экспедиция Дежнёва.","type":"written","q":"16. Укажите российского монарха, в период правления которого произошло событие, юбилею которого посвящена данная марка. Используя изображение, приведите одно любое обоснование вашего ответа.","rubric":"1) монарх: Алексей Михайлович;\n\n2) объяснение: исходя из надписи на марке, можно сказать, что она посвящена 300-летию открытия пролива между Азией и Америкой. Также виден год издания марки - 1948-й. Так, проведя математическое вычисление (1948 - 300 = 1648) получаем 1648 г. Таким образом, известно что с 1645 г. российским монархом был Алексей Михайлович, при котором и произошла экспедиция Дежнёва.","hint":"Ответьте на каждый пункт задания отдельно и подкрепите вывод конкретными историческими фактами.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/cWfiTzPHiBMS_%25D0%25A1%25D0%25BD%25D0%25B8%25D0%25BC%25D0%25BE%25D0%25BA%2520%25D1%258D%25D0%25BA%25D1%2580%25D0%25B0%25D0%25BD%25D0%25B0%25C2%25A0%25E2%2580%2594%25202026-10-15%2520%25D0%25B2%25C2%25A016.31.53.png\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","answer":"См. образец и критерии самопроверки"},{"id":"history-nov11-2-q2","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/ce54faa4-2826-4c28-be4e-d6de0beb23c6","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 2","ex":"1) цифра: 2\n\n2) событие: восстание Степана Разина.","type":"written","q":"17. Какая из представленных ниже картин иллюстрирует событие, произошедшее в том же веке, в которым была совершена экспедиция, маршрут которой изображён на марке? В ответе запишите цифру, которой обозначено это изображение. Укажите название этого события.","rubric":"1) цифра: 2\n\n2) событие: восстание Степана Разина.","hint":"Ответьте на каждый пункт задания отдельно и подкрепите вывод конкретными историческими фактами.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/cWfiTzPHiBMS_%25D0%25A1%25D0%25BD%25D0%25B8%25D0%25BC%25D0%25BE%25D0%25BA%2520%25D1%258D%25D0%25BA%25D1%2580%25D0%25B0%25D0%25BD%25D0%25B0%25C2%25A0%25E2%2580%2594%25202026-10-15%2520%25D0%25B2%25C2%25A016.31.53.png\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a> · <a href=\"https://cdn.studycats.ru/wuiFsbTQ2U04_%25D0%25A1%25D0%25BD%25D0%25B8%25D0%25BC%25D0%25BE%25D0%25BA%2520%25D1%258D%25D0%25BA%25D1%2580%25D0%25B0%25D0%25BD%25D0%25B0%25C2%25A0%25E2%2580%2594%25202026-10-15%2520%25D0%25B2%25C2%25A016.43.12.png\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 2</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","answer":"См. образец и критерии самопроверки"},{"id":"history-nov11-2-q3","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/ce54faa4-2826-4c28-be4e-d6de0beb23c6","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 3","ex":"а) Внутриполитической причиной издания Соборного уложения является социальная напряженность в государстве. Так, после Соляного бунта 1648 года, правительство понимало, что государственная система нуждается в серьезных реформах. Так, например, происходил рост взяточничества и злоупотребление своими должностями, ярким примером которого является Борис Морозов. Для реформирования государственной системы был необходим обновленный свод законов вместо устаревшего Судебника Ивана IV 1550 года. Таким образом, социальная напряжённость и необходимость совершенствования законодательства стали одними из причин издания Соборного уложения в 1649 г.\n\nб) Социально-экономическим последствием издания Соборного уложения является окончательное закрепощение крестьян. Соборное уложение 1649 года устанавливало бессрочный сыск беглых крестьян. Так, по уложению отменялись урочные лета: теперь бежавших от землевладельца крестьян могли искать бессрочно, что в свою очередь окончательно закрепляло крепостное право в стране. Таким образом, это стало последствием издания Соборного уложения в 1649 г.\n\nв) Политическим последствием издания Соборного уложения является укрепление самодержавия. Так, например, по Соборному уложению устанавливались наказания за посягательство на жизнь царя и его семьи, защищалась их честь, вводилось понятие государственного преступления. Подобные меры укрепляли личную власть царя и дали толчок к развитию абсолютизма в России. Таким образом, это стало последствием издания Соборного уложения в 1649 г.","type":"written","q":"19. В 1649 году был утвержден новый свод законов – Соборное уложение, целью которого явилась новая кодификация законов. Укажите:\n\nа) внутриполитическую причину издания Соборного уложения;\n\nб) социально-экономическое последствие издания Соборного уложения;\n\nв) политическое последствие издания Соборного уложения.\n\nОтвет оформите в следующем виде (обязательно соблюдайте порядок заполнения пунктов ответа).\n\nа)  ________________________________________________________________\n\nб)  ________________________________________________________________\n\nв)  ________________________________________________________________","rubric":"а) Внутриполитической причиной издания Соборного уложения является социальная напряженность в государстве. Так, после Соляного бунта 1648 года, правительство понимало, что государственная система нуждается в серьезных реформах. Так, например, происходил рост взяточничества и злоупотребление своими должностями, ярким примером которого является Борис Морозов. Для реформирования государственной системы был необходим обновленный свод законов вместо устаревшего Судебника Ивана IV 1550 года. Таким образом, социальная напряжённость и необходимость совершенствования законодательства стали одними из причин издания Соборного уложения в 1649 г.\n\nб) Социально-экономическим последствием издания Соборного уложения является окончательное закрепощение крестьян. Соборное уложение 1649 года устанавливало бессрочный сыск беглых крестьян. Так, по уложению отменялись урочные лета: теперь бежавших от землевладельца крестьян могли искать бессрочно, что в свою очередь окончательно закрепляло крепостное право в стране. Таким образом, это стало последствием издания Соборного уложения в 1649 г.\n\nв) Политическим последствием издания Соборного уложения является укрепление самодержавия. Так, например, по Соборному уложению устанавливались наказания за посягательство на жизнь царя и его семьи, защищалась их честь, вводилось понятие государственного преступления. Подобные меры укрепляли личную власть царя и дали толчок к развитию абсолютизма в России. Таким образом, это стало последствием издания Соборного уложения в 1649 г.","hint":"Ответьте на каждый пункт задания отдельно и подкрепите вывод конкретными историческими фактами.","answer":"См. образец и критерии самопроверки"},{"id":"history-nov11-2-q4","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/ce54faa4-2826-4c28-be4e-d6de0beb23c6","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 4","ex":"1) ответ на первый вопрос: первые мануфактуры в России (тульские железоделательные заводы) появились в царствование Михаила Фёдоровича;\n\n2) ответ на второй вопрос: особенность российских мануфактур заключалась в большой роли казны и иностранцев, а также в дефиците рабочей силы.","type":"written","q":"20. Вспомните смысл понятия «мануфактура» и ответьте на вопросы. В царствование какого государя появились первые крупные железоделательные мануфактуры в России? В чём заключалась особенность российских мануфактур XVII в.?","rubric":"1) ответ на первый вопрос: первые мануфактуры в России (тульские железоделательные заводы) появились в царствование Михаила Фёдоровича;\n\n2) ответ на второй вопрос: особенность российских мануфактур заключалась в большой роли казны и иностранцев, а также в дефиците рабочей силы.","hint":"Ответьте на каждый пункт задания отдельно и подкрепите вывод конкретными историческими фактами.","answer":"См. образец и критерии самопроверки"},{"id":"history-nov11-2-q5","subject":"history","section":"course","topic":"Тема 8. Первые Романовы","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/ce54faa4-2826-4c28-be4e-d6de0beb23c6","sourceLabel":"StudyCats · Тема 8. Первые Романовы · вопрос 5","ex":"Тезис: \"Существенное место во внешней политике Михаила Фёдоровича и Алексея Михайловича занимало западное направление, а также изучение и освоение сибирских и дальневосточных земель\";\n\nОбоснования тезиса:\n\n1) Так, например, в правление Михаила Фёдоровича произошла война с Речью Посполитой в 1632-1634 гг. Основной задачей было взятие Смоленска и возвращение части земель, утраченных в ходе польской интервенции в годы Смутного времени. При Алексее Михайловиче в 1654-1667 годах тоже шла война с Речью Посполитой. Она была продолжением ряда войн между Россией и Речью Посполитой. Аналогичной целью войны стало возвращение западнорусских земель, которые отошли к Речи Посполитой в Смутное время, и которые не удалось отвоевать в ходе предыдущей неудачной Смоленской войны 1632-1634 гг. Таким образом, оба царя стремились укрепить позиции России на западном направлении и вернуть ранее утраченные территории.\n\n2) Кроме того, при Михаиле Фёдоровиче в 1643 г. Василий Поярков возглавил первый поход на Амур. Основной целю экспедиции было изучить территории, находящиеся по соседству, отыскать новые земли, которые были богаты полезными ископаемыми. Именно в ходе данной экспедиции была открыта богатая Даурия. При Алексее Михайловиче Ерофей Хабаров, дважды побывав на Амуре, составил «Чертёж реке Амуру» – детальный план территории Даурии, который был отправлен в Москву. Именно он положил начало заселению этой территории. Таким образом, при обоих царях продолжалось изучение и освоение дальневосточных территорий.","type":"written","q":"21. Запишите один любой тезис (обобщённое оценочное суждение), содержащий информацию о сходстве во внешней политике царей Михаила Фёдоровича и Алексея Михайловича по какому(-им)-либо признаку(-ам). Приведите два обоснования этого тезиса. Каждое обоснование должно содержать два исторических факта (по одному для каждого из сравниваемых объектов). При обосновании тезиса избегайте рассуждений общего характера.\n\nОтвет оформите в следующем виде:\n\nТезис: _______________________________________________\n\nОбоснование тезиса:\n\n1) _______________________________________________\n\n2) _______________________________________________","rubric":"Тезис: \"Существенное место во внешней политике Михаила Фёдоровича и Алексея Михайловича занимало западное направление, а также изучение и освоение сибирских и дальневосточных земель\";\n\nОбоснования тезиса:\n\n1) Так, например, в правление Михаила Фёдоровича произошла война с Речью Посполитой в 1632-1634 гг. Основной задачей было взятие Смоленска и возвращение части земель, утраченных в ходе польской интервенции в годы Смутного времени. При Алексее Михайловиче в 1654-1667 годах тоже шла война с Речью Посполитой. Она была продолжением ряда войн между Россией и Речью Посполитой. Аналогичной целью войны стало возвращение западнорусских земель, которые отошли к Речи Посполитой в Смутное время, и которые не удалось отвоевать в ходе предыдущей неудачной Смоленской войны 1632-1634 гг. Таким образом, оба царя стремились укрепить позиции России на западном направлении и вернуть ранее утраченные территории.\n\n2) Кроме того, при Михаиле Фёдоровиче в 1643 г. Василий Поярков возглавил первый поход на Амур. Основной целю экспедиции было изучить территории, находящиеся по соседству, отыскать новые земли, которые были богаты полезными ископаемыми. Именно в ходе данной экспедиции была открыта богатая Даурия. При Алексее Михайловиче Ерофей Хабаров, дважды побывав на Амуре, составил «Чертёж реке Амуру» – детальный план территории Даурии, который был отправлен в Москву. Именно он положил начало заселению этой территории. Таким образом, при обоих царях продолжалось изучение и освоение дальневосточных территорий.","hint":"Ответьте на каждый пункт задания отдельно и подкрепите вывод конкретными историческими фактами.","answer":"См. образец и критерии самопроверки"}]},{"id":"history-course-nov11-3","subject":"history","section":"course","topic":"Тема 9. Пётр I","topicOrder":9,"part":1,"cardTitle":"Тест по теме","label":"Тест по теме","title":"Тема 9. Пётр I · Тест по теме","period":"История России","description":"30 заданий по теме. Подсказки и разборы; изображения — по ссылкам на оригинал.","questions":[{"id":"history-nov11-3-q1","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 1","ex":"А) Табель о рангах - закон о порядке государственной службы, был введён императором Петром I в 1722 году.\n\nБ) По окончании Северной войны в 1721 году Петру I получил титул Императора Всероссийского, что ознаменовало превращение России в империю.\n\nВ) Город Санкт-Петербург был основан Петром I в 1703 году.\n\nГ) Правительствующий Сенат был учреждён Петром I в 1711 году.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1703 г.","1714 г.","1722 г.","1711 г.","1700 г.","1721 г."],"rows":[{"id":"row1","label":"введение Табели о рангах","answer":"1722 г."},{"id":"row2","label":"учреждение титула императора","answer":"1721 г."},{"id":"row3","label":"основание Санкт-Петербурга","answer":"1703 г."},{"id":"row4","label":"учреждение Сената","answer":"1711 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q2","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 2","ex":"А) Первый Азовский поход Петра I состоялся в 1695 году. Он был предпринят против Османской империи с целью получения выхода к Азовскому и Чёрному морям, но закончился неудачей.\n\nБ) Морское сражение у острова Гренгам между русским и шведским флотами произошло в 1720 году и завершилось победой России.\n\nВ) «Табель о рангах» - законодательный акт, определявший порядок прохождения государственной службы - был принят в 1722 году.\n\nГ) Указ о единонаследии был издан Петром I в 1714 году. Он приравнял поместья к вотчинам и запретил дробление земельной собственности при наследовании, закрепляя её за одним сыном.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1722 г.","1695 г.","1715 г.","1720 г.","1721 г.","1714 г."],"rows":[{"id":"row1","label":"первый Азовский поход Петра I","answer":"1695 г."},{"id":"row2","label":"сражение у острова Гренгам","answer":"1720 г."},{"id":"row3","label":"принятие «Табели о рангах»","answer":"1722 г."},{"id":"row4","label":"Указ о единонаследии","answer":"1714 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q3","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 3","ex":"А) В 1708 году Пётр I провёл первую областную реформу, разделив Россию на 8 губерний.\n\nБ) Подушная подать была введена указом Петра I в 1724 году. Она заменила подворное налогообложение и распространялась на всё мужское население податных сословий.\n\nВ) Прутский поход русской армии под командованием Петра I против Османской империи состоялся в 1711 году.\n\nГ) Константинопольский мирный договор между Россией и Османской империей был подписан в 1700 году.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1724 г.","1700 г.","1703 г.","1708 г.","1720 г.","1711 г."],"rows":[{"id":"row1","label":"создание губерний","answer":"1708 г."},{"id":"row2","label":"введение подушной подати","answer":"1724 г."},{"id":"row3","label":"Прутский поход","answer":"1711 г."},{"id":"row4","label":"Константинопольский мир с Турцией","answer":"1700 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q4","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 4","ex":"А) Правительствующий Сенат был учреждён Петром I в 1711 году.\n\nБ) Начало создания коллегий относится к 1718 году.\n\nВ) Мирный договор со Швецией был подписан в 1721 году (Ништадтский мир).\n\nГ) Указ о престолонаследии был издан Петром I в 1722 году. Он отменял традиционный принцип наследования престола прямым потомком по мужской линии и предоставлял царю право самому назначать наследника.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1718 г.","1722 г.","1721 г.","1700 г.","1711 г.","1705 г."],"rows":[{"id":"row1","label":"учреждение Сената","answer":"1711 г."},{"id":"row2","label":"учреждение коллегий","answer":"1718 г."},{"id":"row3","label":"Ништадтский мир со Швецией","answer":"1721 г."},{"id":"row4","label":"подписание указа о наследии престола","answer":"1722 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q5","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 5","ex":"А) Нерчинский договор - первый русско-китайский договор, подписанный в 1689 году в Нерчинске. Он установил границу между Русским царством и Цинской империей.\n\nБ) Подушная подать была введена в 1724 году в ходе налоговой реформы Петра I. Она заменила подворное обложение: налог взимался с каждой души мужского пола податных сословий, что увеличило налоговые поступления в казну.\n\nВ) Битва у деревни Лесной была в 1708 году в ходе Северной войны. Русский корволант под командованием Петра I разгромил шведский отряд генерала Левенгаупта, что лишило шведскую армию Карла XII продовольствия и боеприпасов. Это сражение называют «матерью Полтавской баталии».\n\nГ) Указ Петра I о престолонаследии был издан в 1722 году. Он отменял древний обычай передачи престола по прямой мужской линии и предоставлял право императору самому назначать наследника.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1689 г.","1701 г.","1708 г.","1722 г.","1724 г.","1721 г."],"rows":[{"id":"row1","label":"Заключение Нерчинского договора с Китаем","answer":"1689 г."},{"id":"row2","label":"Введение подушной подати","answer":"1724 г."},{"id":"row3","label":"Битва у деревни Лесной","answer":"1708 г."},{"id":"row4","label":"Указ о престолонаследии","answer":"1722 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q6","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 6","ex":"А) Святейший Правительствующий Синод был учреждён в 1721 году по указу Петра I вместо упразднённого патриаршества. Синод стал высшим органом управления Русской православной церкви, подчинённым императору через обер-прокурора.\n\nБ) Указом Петра I в 1708 году страна была разделена на 8 губерний. Губернская реформа укрепила центральную власть на местах и упростила сбор налогов.\n\nВ) Правительствующий Сенат был учреждён указом Петра I в 1711 году как высший орган государственного управления, законодательства и суда, временно заменявший царя во время его отсутствия.\n\nГ) Гренгамское сражение произошло в 1720 году у острова Гренгам в ходе Северной войны.","type":"match","q":"Установите соответствие между событиями и годами: к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["1711 г.","1703 г.","1720 г.","1708 г.","1721 г.","1709 г."],"rows":[{"id":"row1","label":"учреждение Синода","answer":"1721 г."},{"id":"row2","label":"Губернская реформа","answer":"1708 г."},{"id":"row3","label":"учреждение Сената","answer":"1711 г."},{"id":"row4","label":"сражение у острова Гренгам","answer":"1720 г."}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q7","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 7","ex":"1) Столетняя война - 1337-1453 гг.\n\n2) морское сражение у мыса Гангут - 1714 г.\n\n3) Стрелецкий бунт - 1698 г.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"Столетняя война"},{"id":"2","label":"морское сражение у мыса Гангут"},{"id":"3","label":"Стрелецкий бунт"}],"answer":["1","3","2"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-3-q8","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 8","ex":"1) битва при деревне Лесной - 1708 г.\n\n2) Полтавская битва - 1709 г.\n\n3) «Славная революция» в Англии - 1688-1689 гг.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"битва при деревне Лесной"},{"id":"2","label":"Полтавская битва"},{"id":"3","label":"«Славная революция» в Англии"}],"answer":["3","1","2"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-3-q9","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 9","ex":"1) учреждение Сената в России - 1711 г.\n\n2) протекторат О. Кромвеля - 1653 г.\n\n3) Астраханское восстание - 1705-1706 гг.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"учреждение Сената в России"},{"id":"2","label":"протекторат О. Кромвеля"},{"id":"3","label":"Астраханское восстание"}],"answer":["2","3","1"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-3-q10","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 10","ex":"1) Смоленская война - 1632-1634 гг.\n\n2) окончание Столетней войны - 1453 г.\n\n3) окончание Северной войны - 1721 г.","type":"order","q":"Расположите в хронологической последовательности исторические события. Запишите цифры, которыми обозначены исторические события, в правильной последовательности.","options":[{"id":"1","label":"Смоленская война"},{"id":"2","label":"окончание Столетней войны"},{"id":"3","label":"окончание Северной войны"}],"answer":["2","1","3"],"hint":"Сначала определите даты событий, затем расположите их по времени."},{"id":"history-nov11-3-q11","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 11","ex":"А) Создание Сената в 1711 году стало важным шагом в реформировании государственного аппарата. Сенат стал высшим органом управления.\n\nБ) Издание первой российской печатной газеты «Ведомости» являлось частью культурных преобразований Петра I, направленных на просвещение общества.\n\nВ) Введение рекрутской повинности позволило создать регулярную армию, что значительно усилило военную мощь Российского государства.\n\nГ) Принятие Петром I титула императора в 1721 году после победы в Северной войне символизировало окончательное укрепление абсолютной монаршей власти и повышение международного статуса Российского государства.","type":"match","q":"Установите соответствие между процессами (явлениями, событиями)и фактами, относящимися к этим процессам (явлениям, событиям). Запишите цифры.","options":["рекрутские наборы","провозглашение России империей","учреждение Сената","первая печатная газета «Ведомости»","строительство мануфактур","Великое посольство"],"rows":[{"id":"row1","label":"совершенствование аппарата управления","answer":"учреждение Сената"},{"id":"row2","label":"реформы в области культуры","answer":"первая печатная газета «Ведомости»"},{"id":"row3","label":"укрепление обороноспособности страны","answer":"рекрутские наборы"},{"id":"row4","label":"усиление власти царя","answer":"провозглашение России империей"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q12","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 12","ex":"А) В 1687 году при регентстве царевны Софьи Алексеевны в Москве была открыта Славяно-греко-латинская академия - первое высшее учебное заведение в России.\n\nБ) Азовские походы (1695–1696) были предприняты Петром I с целью выхода к Азовскому морю. Первый поход (1695) оказался неудачным, второй (1696) увенчался взятием турецкой крепости Азов.\n\nВ) Святейший Правительствующий Синод был учреждён в 1721 году по указу Петра I вместо упразднённого патриаршества. Синод стал высшим органом управления Русской православной церкви, подчинённым императору через обер-прокурора, что завершило процесс огосударствления церкви.\n\nГ) Битва под Нарвой 1700 года - первое крупное сражение Северной войны между русской армией Петра I и шведской армией Карла XII. Русские войска потерпели тяжёлое поражение, но это послужило стимулом для военных реформ и создания регулярной армии.","type":"match","q":"Установите соответствие между процессами (явлениями, событиями) и фактами, относящимися к этим процессам (явлениям, событиям): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["издание Указа о престолонаследии","учреждение Синода","создание губерний","поражение под Нарвой","открытие Славяно-греко-латинской академии","Азовские походы"],"rows":[{"id":"row1","label":"внутренняя политика Софьи Алексеевны","answer":"открытие Славяно-греко-латинской академии"},{"id":"row2","label":"внешняя политика Петра I до Северной войны","answer":"Азовские походы"},{"id":"row3","label":"подчинение церкви государству в XVIII в.","answer":"учреждение Синода"},{"id":"row4","label":"Северная война","answer":"поражение под Нарвой"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q13","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 13","ex":"А) Пётр I провел налоговую реформу, заменив подворное обложение единой подушной податью с каждой мужской души.\n\nБ) В 1720-х годах был издан Генеральный регламент - устав государственной гражданской службы, определивший единообразную организацию и делопроизводство в новых органах управления - коллегиях.\n\nВ) В 1701 году в Москве была открыта Школа математических и навигацких наук — первое в России специализированное военно-морское учебное заведение, положившее начало системе профессионального военного образования.\n\nГ) Берг-привилегия 1719 года разрешала всем подданным искать полезные ископаемые и строить заводы, обеспечивая поддержку отечественной промышленности и защиту от иностранной конкуренции.","type":"match","q":"Установите соответствие между процессами (явлениями, событиями) и фактами, относящимися к этим процессам (явлениям, событиям): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["отмена местничества в России","издание указа об учреждении Академии наук","издание Генерального регламента для коллегий","объявление Берг-привилегии","создание Навигацкой школы","введение единой подушной подати"],"rows":[{"id":"row1","label":"налоговые реформы Петра I","answer":"введение единой подушной подати"},{"id":"row2","label":"Петровские реформы органов центральной власти","answer":"издание Генерального регламента для коллегий"},{"id":"row3","label":"реформы военного образования в первой четверти XVIII в.","answer":"создание Навигацкой школы"},{"id":"row4","label":"Петровская протекционистская экономическая политика","answer":"объявление Берг-привилегии"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q14","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 14","ex":"А) Город Черкасск - один из восстания донских казаков 1707-1708 гг. Здесь был убит предводитель восстания - Кондратий Булавин.\n\nБ) Астраханское восстание 1705-1706 гг. объединило сразу несколько сословных групп в неприятии налоговой политики государства.\n\nВ) В 1701-1702 гг. был основан Невьянский завод. В том же 1702 г. завод был передан Петром I из казны тульскому оружейнику Никите Демидовичу Антуфьеву (Демидову).\n\nГ) Кунсткамера (кабинет редкостей) - первый музей в России, учреждённый в 1714 г. (в 1724 присоединена к Академии Наук) царём Петром I в Санкт-Петербурге.","type":"match","q":"Заполните пустые ячейки таблицы, используя приведённый ниже список пропущенных элементов: для каждого пропуска, обозначенного буквой, выберите номер нужного элемента.","bodyHtml":"<table style=\"min-width: 579px;\"><colgroup><col style=\"min-width: 100px;\"><col style=\"width: 379px;\"><col style=\"min-width: 100px;\"></colgroup><tbody><tr><td colspan=\"1\" rowspan=\"1\"><p><strong>Географический объект</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>Событие (явление, процесс)</strong></p></td><td colspan=\"1\" rowspan=\"1\"><p><strong>Время, когда произошло событие (явление, процесс)</strong></p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Черкасск</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (А)</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Б)</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (В)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Начало восстания стрельцов, казаков, солдат, посадских, работных и беглых людей, произошедшее вследствие введения новых налогов и жестокости воеводы Тимофея Ржевского</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Г)</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>Невьянск</p></td><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Д)</p></td><td colspan=\"1\" rowspan=\"1\"><p>1701 г.</p></td></tr><tr><td colspan=\"1\" rowspan=\"1\"><p>_____________________ (Е)</p></td><td colspan=\"1\" rowspan=\"1\"><p>Открытие Кунсткамеры</p></td><td colspan=\"1\" rowspan=\"1\"><p>1714 г. (1724 г.)</p></td></tr></tbody></table>","options":["Астрахань.","Подавление восстания Кондратия Булавина.","1721 г.","1708 г.","Санкт-Петербург.","Москва.","Основание первого «демидовского» завода на Урале.","Открытие Славяно-греко-латинской академии.","1705 г."],"rows":[{"id":"row1","label":"Пропуск А","answer":"Подавление восстания Кондратия Булавина."},{"id":"row2","label":"Пропуск Б","answer":"1708 г."},{"id":"row3","label":"Пропуск В","answer":"Астрахань."},{"id":"row4","label":"Пропуск Г","answer":"1705 г."},{"id":"row5","label":"Пропуск Д","answer":"Основание первого «демидовского» завода на Урале."},{"id":"row6","label":"Пропуск Е","answer":"Санкт-Петербург."}],"hint":"Для каждого буквенного пропуска определите, что требуется: место, событие или дата."},{"id":"history-nov11-3-q15","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 15","ex":"А) Патрик Гордон - иностранец, находившийся на русской службе еще со времен Алексея Михайловича. Последняя военная акция, в которой он участвовал — Азовские походы 1695-1696 гг.\n\nБ) Стрелецкий бунт 1682 г. называют «Хованщиной» по имени фактического вождя мятежников - Ивана Хованского.\n\nВ) Один из трех руководителей Великого посольства Петра I — Прокофий Возницын. Двое других - Франц Лефорт и Федор Головин.\n\nГ) Владимир Атласов - русский землепроходец, в 1697-1698 годах возглавлял первый поход русских по Камчатке.","type":"match","q":"Установите соответствие между событиями (явлениями, процессами) и участниками этих событий (явлений, процессов): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Владимир Атласов","Патрик Гордон","Василий Голицын","Иван Хованский","Афанасий Ордин-Нащокин","Прокофий Возницын"],"rows":[{"id":"row1","label":"второй Азовский поход Петра I","answer":"Патрик Гордон"},{"id":"row2","label":"стрелецкий бунт 1682 г.","answer":"Иван Хованский"},{"id":"row3","label":"Великое посольство","answer":"Прокофий Возницын"},{"id":"row4","label":"Камчатская экспедиция 1697-1698 гг.","answer":"Владимир Атласов"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q16","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 16","ex":"А) Стрелецкий бунт 1682 года (Хованщина) вспыхнул после смерти царя Фёдора Алексеевича. Его возглавил князь Иван Андреевич Хованский, глава Стрелецкого приказа, который попытался использовать недовольство стрельцов для захвата власти.\n\nБ) Крымские походы 1687 и 1689 годов возглавлял князь Василий Васильевич Голицын, фаворит царевны Софьи.\n\nВ) Петропавловский собор в Санкт-Петербурге был построен в 1712–1733 годах по проекту архитектора Доменико Трезини.\n\nГ) В 1722 году указом Петра I была учреждена должность генерал-прокурора Сената. Первым генерал-прокурором был назначен Павел Иванович Ягужинский.","type":"match","q":"Установите соответствие между событиями (явлениями, процессами) и участниками этих событий (явлений, процессов): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Доменико Трезини","П. И. Ягужинский","В. В. Голицын","И. А. Хованский","Ф. М. Апраксин","А. И. Репнин"],"rows":[{"id":"row1","label":"Стрелецкий бунт 1682 г.","answer":"И. А. Хованский"},{"id":"row2","label":"Крымские походы 1687 и 1689 гг.","answer":"В. В. Голицын"},{"id":"row3","label":"Строительство Петропавловского собора","answer":"Доменико Трезини"},{"id":"row4","label":"Учреждение должности генерал-прокурора","answer":"П. И. Ягужинский"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q17","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 17","ex":"А) Павел Иванович Ягужинский был первым генерал-прокурором.\n\nБ) Никита Демидов по указу Петра I создал на Урале металлургические заводы, ставшие основой российской горнозаводской промышленности.\n\nВ) Борис Петрович Шереметев в 1706 году руководил подавлением Астраханского восстания (1705-1706 гг.).\n\nГ) Александр Данилович Меншиков командовал в битве у деревни Лесной в 1708 году.","type":"match","q":"Установите соответствие между событиями (явлениями, процессами) и участниками этих событий (явлений, процессов): к каждой позиции первого столбца подберите соответствующую позицию из второго столбца.","options":["Никита Демидов","Александр Меншиков","Павел Ягужинский","царевна Софья","Борис Шереметев","Михаил Ломоносов"],"rows":[{"id":"row1","label":"деятельность Генеральной прокуратуры","answer":"Павел Ягужинский"},{"id":"row2","label":"развитие Уральского промышленного района","answer":"Никита Демидов"},{"id":"row3","label":"подавление Астраханского восстания","answer":"Борис Шереметев"},{"id":"row4","label":"командование в битве у д. Лесной","answer":"Александр Меншиков"}],"hint":"Сопоставьте каждый пункт с датой, участником или событием; лишние варианты использовать не требуется."},{"id":"history-nov11-3-q18","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 18","ex":"1) ДА, верно. Указ о единонаследии, фрагмент которого представлен в тексте, был издан в 1714 г.\n\n2) НЕТ, неверно. Указ о единонаследии издал Петр I.\n\n3) ДА, верно. Указ запрещал продажу поместий и вотчин.\n\n4) НЕТ, неверно. Указ о единонаследии был отменен Анной Иоанновной в 1730 г.\n\n5) НЕТ, неверно. Текст свидетельствует о том, что недвижимое имущество будет наследовать тот, на кого падет выбор в завещании. Таким образом, это совершенно необязательно должен быть старший сын.\n\n6) ДА, верно. Текст указа свидетельствует о том, что недвижимое имущество может получить только один человек, остальные (включая дочерей) довольствуются наследованием движимого имущества. Именно поэтому закон 1714 г. называют указом о единонаследии.","type":"multi","q":"Прочтите отрывок из исторического источника.\n\n«...Понеже разделением имений после отцов детям недвижимых, великой есть вред в государстве нашем, как интересам государственным, так и подданным и самим фамилиям подение... За благо изобретено чинить по сему, как объявлено ниже сего:\n\n1) Всем недвижимых вещей, то есть родовых, выслуженных и купленных вотчин и поместий, а также и дворцов и лавок не продавать и не закладывать, но обращаться в род таким образом:\n\n2) Кто имеет сыновей и ему же аще хощет, единому из них оных дать недвижимость чрез духовную, тому в наследие и будет; другие же дети обоего пола да награждены будут движимыми имении, которые должен отец их или мать разделити им, при себе как сыновьям, так и дочерям, колико их будет, по своей воли, кроме оного одного, который в недвижимых наследником будет. А ежели у оного сыновей не будет, а имеет дочерей, то должен определити таким же образом. А буде при себе не определит, тогда определится указом недвижимое по первенству большому сыну в наследие, а движимое другим равною частью разделено будет, то ж разумеет и о дочерях...»\n\nКакие утверждения о тексте верны?","options":[{"id":"1","label":"Указ, отрывок из которого представлен в тексте, был издан в 1714 г."},{"id":"2","label":"Данный указ издала Екатерина II."},{"id":"3","label":"Указ существенно ограничивал возможности продажи поместий и вотчин."},{"id":"4","label":"Указ, отрывок из которого представлен в тексте, был отменен Екатериной II."},{"id":"5","label":"Согласно тексту источника, недвижимое имущество имели право наследовать только старшие сыновья землевладельцев."},{"id":"6","label":"Согласно тексту источника, недвижимое имущество мог наследовать только один сын землевладельца, а остальные довольствовались наследованием движимого имущества."}],"answer":["1","3","6"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-3-q19","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 19","ex":"1) ДА, верно. Левенгаупт должен был соединиться с Карлом XII и передать ему обоз с продовольствием и оружием.\n\n2) НЕТ, неверно. Битва при Лесной произошла в 1708 г.\n\n3) ДА, верно. Северная война является наиболее важной из русско-шведских войн.\n\n4) ДА, верно. В 1708 г. на Дону происходило восстание Булавина.\n\n5) НЕТ, неверно. Согласно тексту источника, российское командование ожидало противника в меньшем количестве, нежели он явился на самом деле.\n\n6) НЕТ, неверно. Франц Лефорт умер в 1699 г. и в событиях Северной войны не участвовал.","type":"multi","q":"Прочтите отрывок из исторического источника.\n\n«В 15 день Государь пришел в село Григорково, и тут получили подлинную ведомость чрез взятых языков, что Левенгаупт маршем своим ело стал поспешать: чего для и Государь с полками своими маршем поспешал, в котором марше имели вожа Жида подкупного от шведов, который нас фальшивым маршем к Днепру привел, сказывая, что Левенгаупт еще не перешел чрез оный (который уже три дня как перешел), куда стали было переправляться, и подлинно он ушел, если бы не встретился шляхтич Петрокович, и сказал о том истину, и правдивым вожем был (а оный Жид за то злодейство повешен), и продолжили тот марш из Григоркова сентября от 16, даже до 27 числа. <…>\n\nПонеже чаяли Левенгаупта в малом числе; <…> и начали пехоту спешивать (для того, что была оная на лошадях), и несколько драгунских полков спешено (понеже пехоты мало было), и строиться к баталии, дабы неприятеля атаковать, и только 3 полка пехотные спешились и 1 драгунский; (а именно: 2 полка гвардии, да полк Ингерманладский и Невский драгунский) тогда нечаянно неприятель из леса пехотою на два наши полка Ингерманландский и Невский фронтом напал, однако же неприятелю места не уступили, но мужественно бились; и понеже неприятель гораздо сильнее был, и с левого своего крыла стал фланг занимать: того ради Семеновский полк против оных пришел и в бой вступил; но неприятель так люден был, что и у онаго фланга захватывать стал: того ради послали по Преображенский полк (которого тогда только 3 батальона было, а четвертый был, как выше помянуто, на Дону), да батальон Астраханский, которые уже гораздо в право было отошли для атаки на левое неприятельское крыло, тотчас поворотились и со фланга на неприятеля нападение учинили, которых увидя неприятель, и не дождався оных, назад в лес уходить начал, за которым сквозь лес гнались, и 4 пехотных знамя, 2 пушки, и полковника Шталя и генерала адъютанта Кноринга, и иных несколько офицеров взяли (которые единогласно сказывали, что их было в бою 13000, кроме авангарда 3000, который у Пропойска был)…»\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения.","options":[{"id":"1","label":"Задачей корпуса Левенгаупта было соединиться с войсками короля Карла XII."},{"id":"2","label":"События, описанные в тексте источника, произошли в 1700 г."},{"id":"3","label":"В тексте источника описываются события русско-шведской войны."},{"id":"4","label":"Одновременно с событиями, описанными в тексте источника, в России происходило восстание донских казаков."},{"id":"5","label":"Согласно тексту источника, российское командование ожидало противника в большем количестве, нежели он явился на самом деле."},{"id":"6","label":"В войне, события которой описываются в тексте источника, принимал участие Франц Лефорт."}],"answer":["1","3","4"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-3-q20","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 20","ex":"1) НЕТ, неверно. А.Л. Ордин-Нащокин жил в XVII веке (умер в 1680 г.) и не мог быть участником посольства 1697 года.\n\n2) ДА, верно. Пётр I отправился в Великое посольство под вымышленным именем.\n\n3) НЕТ, неверно. Великое посольство состоялось в 1697–1698 годах, что относится к последней четверти XVII века.\n\n4) ДА, верно. Одной из главных дипломатических целей Великого посольства было найти союзников для продолжения войны с Османской империей (в рамках Священной лиги).\n\n5) ДА, верно. В отрывке упоминается, что купец хотел видеть великого князя «за работой плотника», и его просьба была исполнена. Это подтверждает, что Пётр работал на голландских верфях.\n\n6) НЕТ, неверно. Пётр I был провозглашён царём в 1682 году, но до 1696 года правил совместно с братом Иваном V (при регентстве Софьи до 1689 г.). Единоличное правление началось с 1696 года.","type":"multi","q":"Прочтите отрывок из записок иностранца.\n\n«В <…> году его царское величество решил предпринять большое путешествие и отправился в дорогу с большою свитою, состоявшею, между прочим, из разных князей и вельмож его государства, двух или трёх послов, священников и других должностных лиц. Один из них ехали в Германию и Вену к германскому императору, другие же – в Италию и Рим к папе; сам же он со многими из вышеупомянутых господ отправился в Голландию и Англию. Но в газетах не смели сообщить о том, что он самолично участвует в этом путешествии, а писалось всегда: \"великое московское посольство\" или \"некоторые князья из великого посольства его царского величества\" были здесь или там...\n\nЕго свита говорила, что они, вероятно, останутся всю зиму в Зандаме, чтобы усовершенствоваться в кораблестроении и других ремёслах...\n\nЕго царское величество осматривал с большим вниманием корабельные верфи и лесопильные мельницы и, между прочим, отправился на мельницу под названием de-kok (повар), чтобы видеть, как изготовляется белая бумага.\n\nОдин правдивый амстердамский торговец рассказывал мне, что какой-то купец в Амстердаме пожелал видеть великого князя за работой плотника и поэтому обратился к корабельному мастеру верфи с просьбой, чтоб тот допустил его и дал ему возможность удовлетворить своё любопытство. Его просьба была исполнена».\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите цифры.","options":[{"id":"1","label":"Одним из упоминаемых в тексте «двух или трёх послов» был А.Л. Ордин-Нащокин."},{"id":"2","label":"Русский царь принимал участие в описываемом в отрывке путешествии под вымышленным именем."},{"id":"3","label":"События, о которых идёт речь в отрывке, произошли в первой четверти XVIII в."},{"id":"4","label":"Одной из целей посольства, упоминаемого в тексте, был поиск союзников для противостояния Османской империи."},{"id":"5","label":"В ходе описываемого путешествия русский царь совершенствовал своё мастерство корабельного плотника на голландской верфи."},{"id":"6","label":"Упоминаемый в тексте русский царь единолично правил страной с 1682 г."}],"answer":["2","4","5"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-3-q21","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 21","ex":"1) НЕТ, неверно. Описывается битва у деревни Лесной (1708 год) - ключевое сражение Северной войны (1700–1721).\n\n2) НЕТ, неверно. Кунерсдорф - сражение 1759 года (Семилетняя война). В тексте описывается битва у Лесной (1708).\n\n3) ДА, верно. Александр Данилович Меншиков командовал русскими войсками в битве у Лесной.\n\n4) ДА, верно. Корпус Левенгаупта вёз обоз с боеприпасами и продовольствием для армии Карла XII. В тексте указано, что русские захватили 17 знамён, 20 тысяч ружей, 6 тысяч бочонков с порохом и 600 тысяч рейхсталеров.\n\n5) НЕТ, неверно. Русским отрядом командовал Пётр I, а также генерал А.Д. Меншиков.\n\n6) ДА, верно. Пётр I назвал победу у Лесной «матерью Полтавской баталии», так как она подорвала силы шведской армии и обеспечила успех под Полтавой (1709).","type":"multi","q":"Прочтите текст.\n\n«Русская армия потеряла 1111 чел. убитыми и 2856 ранеными. Шведы - не менее 6500 человек. Русские взяли 17 знамён, 20 тысяч ружей, 6 тысяч бочонков с порохом и 600 тысяч шведских рейхсталеров золотом. Итогом стало уничтожение корпуса Левенгаупта, только половину солдат генерал привёл к своему королю. Числом они пополнили шведскую армию, но одновременно принесли слух о силе русской армии, от которой бежали. Левенгаупту не доверили командование войсками, он оставался в армии без определённой должности и от шведских офицеров получил презрительное прозвище «волонтёр» — доброволец.\n\nВ стратегическом отношении шведская армия оказалась без боеприпасов и пороха, снаряжения и подкреплений, что в дальнейшем сыграло важную роль в исходе Полтавской битвы, где из-за отсутствия пороха шведы были вынуждены отказаться от использования артиллерии.\n\nПолитическим итогом битвы стало и изменение баланса сил в пользу России: возможный союзник шведов - Османская империя - отказалась от прямой помощи Карлу XII».\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Сражение произошло во время Семилетней войны."},{"id":"2","label":"Описано сражение при Кунерсдорфе."},{"id":"3","label":"Участником боя был А. Д. Меншиков."},{"id":"4","label":"Противник потерял не только солдат, но и оружие, снаряжение, порох, которые был намерен доставить основным силам шведов."},{"id":"5","label":"Русской армией командовал С.Ф. Апраксин."},{"id":"6","label":"Русский царь назвал описанную победу «матерью Полтавской баталии»."}],"answer":["3","4","6"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-3-q22","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 22","ex":"1) НЕТ, неверно. В отрывке описано Полтавское сражение 1709 года - ключевая битва Северной войны (1700-1721 гг.) со Швецией, а не русско-турецкой войны.\n\n2) НЕТ, неверно. Александр Меншиков был сослан в Берёзов в 1727 году при Петре II, а не в период правления Екатерины I.\n\n3) ДА, верно. Борис Шереметев действительно командовал русскими войсками при взятии Нарвы в 1704 году во время Северной войны.\n\n4) ДА, верно. Пропущенное имя - Пётр I. В 1721 году после окончания Северной войны он первым из русских монархов принял титул императора.\n\n5) НЕТ, неверно. Все указанные военачальники (Меншиков, Шереметев, Баур, Брюс) действовали в период Петра I и не дожили до правления Екатерины II (1762-1796 гг.).\n\n6) ДА, верно. В тексте прямо указано: «центром боевых порядков командовал сам его царское величество» и упоминается, что «шляпа на нём пулею пробита», что подтверждает личное участие Петра I в Полтавской битве.","type":"multi","q":"Прочтите отрывок из воспоминаний современника.\n\n«С нашей стороны правое крыло кавалерии командовал генерал-лейтенант Баур ...левое же крыло командовал его светлость князь Меншиков, понеже тамо его пребытие потребнейше было. А центром боевых порядков командовал сам его царское величество... и при том господин генерал-фелтьмаршал Шереметев, также генералы от инфантерии князь Репнин и Аларт... А артиллериею управлял генерал-порутчик от артиллерии Брюс. И всякой в своём назначенном месте управляли со изрядным опыты мужества и воинского искусства своего. И как войско наше таковым образом в ордер баталии установясь, на неприятеля пошло, и тогда в 9-м часу перед полуднем атака и жестокой огонь с обоих сторон начался, которая атака от наших войск с такою храбростию учинена, что вся неприятельская армия по получасном бою с малым уроном наших войск... как кавалерия, так и инфантерия опровергнута, так что шведская инфантерия не единожды потом не остановилась, но без остановки от наших шпагами, штыками и пиками колота, и даже до обретающегося вблизи лесу, яко скоты, гнаны и биты...\n\nИ тако, милостию Всевышнего, совершенная виктория, которой подобной мало слыхано и видано, с лёгким трудом против гордого неприятеля чрез его царского величества славное оружие и персональной храброй и мудрой привод одержана, ибо его величество в том воистинно свою храбрость, мудрое великодушие и воинское искусство, не опасаясь никакого страха... в высшем градусе показал, и при том шляпа на нём пулею пробита».\n\nИспользуя отрывок и знания по истории, выберите в приведённом списке верные суждения. Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"В отрывке описаны события русско-турецкой войны."},{"id":"2","label":"Князь Меншиков, упомянутый в отрывке, был сослан в Берёзов в период правления Екатерины I."},{"id":"3","label":"Генерал-фельдмаршал Шереметев, упомянутый в отрывке, сыграл важную роль во взятии Нарвы."},{"id":"4","label":"Царь, имя которого пропущено в отрывке, первым получил титул императора."},{"id":"5","label":"Упоминаемые в отрывке генералы русской армии были современниками Екатерины II."},{"id":"6","label":"В сражении, которое описывается в отрывке, принимал личное участие русский царь."}],"answer":["3","4","6"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий."},{"id":"history-nov11-3-q23","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 23","ex":"Северная война, которая отражена на схеме, завершилась в 1721 г. подписанием Ништадтского мирного договора.","type":"short","q":"Заполните пропуск в предложении (укажите год). «Война, ход которой представлен на схеме, завершилась в 17______________ году». Ответ запишите словом (словосочетанием).","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/HPveWm3iorSj_jV4AHNBThTUy_65tqJCHUNDYVZY3EFApZ-H0wGlFvZ4bk6S_ZlzwGGNFUe6H_l5HCMrBJo9dSeq-i4Vo_CUYeLZLVn6wre1MFs0o5%2520%281%29.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["двадцатьпервом","двадцатьпервый","двадцать первом","двадцать первый","21","1721"],"answer":"двадцатьпервом"},{"id":"history-nov11-3-q24","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 24","ex":"Цифрой «7» отмечена крепость Корела. Шведы называли ее также Кексгольм.","type":"short","q":"Запишите название крепости, отмеченной на карте цифрой «7».","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/Sf1xurhJrt7r_jV4AHNBThTUy_65tqJCHUNDYVZY3EFApZ-H0wGlFvZ4bk6S_ZlzwGGNFUe6H_l5HCMrBJo9dSeq-i4Vo_CUYeLZLVn6wre1MFs0o5%2520%281%29.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["корела","карела","кексгольм"],"answer":"корела"},{"id":"history-nov11-3-q25","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 25","ex":"Для решения нужно найти на карте условное обозначение для мирного договора (два флажка - белый и черный). Договор, завершивший Северную войну, был заключен в 1721 г. в Ништадте.","type":"short","q":"Прочтите текст о событиях, отражённых на схеме, и, используя схему, укажите в именительном падеже название города, которое пропущено («_________________») в этом тексте.\n\n«После смерти короля Шведское государство продолжило военные действия. Расчет был на союз с Англией, но он не состоялся: русский флот разгромил шведов у о. Гренгам (входит в группу Аландских островов), после чего англичане отказались от перспективы активной поддержки Швеции. На следующий год после победы при Гренгаме в _____________ был заключен мирный договор…»","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/ZeXNd8ZMkWOU_jV4AHNBThTUy_65tqJCHUNDYVZY3EFApZ-H0wGlFvZ4bk6S_ZlzwGGNFUe6H_l5HCMrBJo9dSeq-i4Vo_CUYeLZLVn6wre1MFs0o5%2520%281%29.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["ништадт","ништадте"],"answer":"ништадт"},{"id":"history-nov11-3-q26","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 26","ex":"1) НЕТ, неверно. На карте видно, что военные действия в 1707-1709 гг. активно велись на территории Левобережной Украины, входившей в состав России.\n\n2) НЕТ, неверно. Цифрой «6» на карте обозначен Псков. Русские войска не брали Псков - этот город и до войны входил в состав Российского государства.\n\n3) ДА, верно. Борис Шереметев - один из трех военачальников Северной войны.\n\n4) НЕТ, неверно. Цифрой «1» отмечено Полтавское сражение. В год, когда состоялась эта битва, Северного союза не существовало. Саксонский князь Август II вышел из войны с Швецией в 1706 г. Восстановление Северного союза произошло уже после Полтавского сражения.\n\n5) НЕТ, неверно. Цифрой «3» обозначена Нарва. Несмотря на знаменитый провал 1700 г., Петру все же удалось взять Нарву спустя четыре года.\n\n6) ДА, верно. Цифрой «5» на карте действительно обозначена Москва. Город обозначен как столица Российского государства (в начале Северной войны столица находилась в Москве, потом перенесена в Санкт-Петербург).","type":"multi","q":"Какие суждения, относящиеся к схеме, являются верными? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"В рамках войны, отраженной на схеме, военные действия на территории Российского государства не осуществлялись."},{"id":"2","label":"Цифрой «6» обозначен город, взятый русскими войсками в 1704 г."},{"id":"3","label":"Участником событий, отраженных на схеме, был Борис Шереметев."},{"id":"4","label":"Поддержку русской армии в сражении, отмеченном на карте цифрой «1», осуществляли саксонские войска."},{"id":"5","label":"Цифрой «3» обозначена крепость, которую русская армия так и не смогла взять в рамках отраженной на карте войны."},{"id":"6","label":"Цифрой «5» на карте обозначена Москва."}],"answer":["3","6"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/Ufc3rV4pgfoJ_jV4AHNBThTUy_65tqJCHUNDYVZY3EFApZ-H0wGlFvZ4bk6S_ZlzwGGNFUe6H_l5HCMrBJo9dSeq-i4Vo_CUYeLZLVn6wre1MFs0o5%2520%281%29.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>"},{"id":"history-nov11-3-q27","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 27","ex":"Буквой «Г» обозначен район Булавинского восстания 1707-1708 гг.","type":"short","q":"Заполните пропуск в предложении (укажите десятилетие): «Народное восстание, район которого обозначен буквой «Г», произошло в тысяча ___________ годах». Ответ запишите словом (словосочетанием).","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/4mOz9Phuew32_%25D0%25B2%25D0%25BE%25D1%2581%25D1%2581%25D1%2582.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["семисотых","семисотых","1700-х","1700"],"answer":"семисотых"},{"id":"history-nov11-3-q28","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 28","ex":"Римской цифрой «I» отмечено Персидское государство, с которым Пётр I воевал в 1722-1723 гг. Буквой «B» отмечена территория, присоединенная к России в результате Персидских походов Петра I.","type":"short","q":"Запишите название государства, отмеченного на карте римской цифрой «I».","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/aU7nwqgiBvVI_%25D0%25B2%25D0%25BE%25D1%2581%25D1%2581%25D1%2582.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["персия","персидскоегосударство","иран"],"answer":"персия"},{"id":"history-nov11-3-q29","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 29","ex":"Значок верфи (см. легенду карты) мы видим рядом с Астраханью. Других городов со знаком верфи, находящихся в устье Волги, на карте нет.","type":"short","q":"Прочтите текст о событиях, отражённых на схеме, и, используя схему, укажите в именительном падеже название города, которое пропущено («_________________») в этом тексте.\n\n«4 ноября 1722 года Пётр I, находясь в ______________, приказал строить верфь «в том месте, где ныне суды осенью на Кутумовой реке вытаскивали». 29 декабря того же года Губернская канцелярия ______________ получила новый указ царя: «При порте для военной службы содержать адмиралтейство и морских адмиралтейских служителей, и для того построить казармы на осмотренном под строение способном месте».\n\nТак в устье Волги появилась верфь для строительства гребных и парусных судов всех классов, кроме кораблей и фрегатов, Каспийской военной флотилии…»","hint":"Определите событие по датам и географическим ориентирам. Следуйте указанной форме ответа.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/eXYNPl3cPkrj_%25D0%25B2%25D0%25BE%25D1%2581%25D1%2581%25D1%2582.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>","aliases":["астрахань","астрахани"],"answer":"астрахань"},{"id":"history-nov11-3-q30","subject":"history","section":"course","topic":"Тема 9. Пётр I","sourceUrl":"https://studycats.ru/lk/homeworks/by-course/1cd9c1aa-2605-439c-967e-323d0f5a1815/test/24d1f495-6b2f-40d3-a92a-04f6cbf1aacb","sourceLabel":"StudyCats · Тема 9. Пётр I · вопрос 30","ex":"1) НЕТ, неверно. Медеплавильные заводы отмечены на карте треугольниками.\n\n2) НЕТ, неверно. Римской цифрой II на карте отмечено Австрийское эрцгерцогство. Итальянского королевства в XVIII в. еще не существовало.\n\n3) ДА, верно. Буквой «А» на карте отмечен Уральский промышленный район, освоенный в эпоху Петра I.\n\n4) ДА, верно. Цифрой «4» отмечен Азов, который утратили в ходе Прутского похода.\n\n5) НЕТ, неверно. Буквой «Б» обозначены территории, не утраченные, а приобретенные Россией по результатам Северной войны 1700-1721 гг.\n\n6) ДА, верно. Цифрой «2» на карте действительно отмечен Смоленск.","type":"multi","q":"Какие суждения, относящиеся к схеме, являются верными? Запишите цифры, под которыми они указаны.","options":[{"id":"1","label":"Большая часть медеплавильных заводов в период, к которому относится карта, находилась южных районах страны."},{"id":"2","label":"Римской цифрой II на карте отмечено Итальянское королевство."},{"id":"3","label":"Буквой «А» на карте отмечен Уральский промышленный район."},{"id":"4","label":"Цифрой «4» отмечен город, утраченный Россией согласно положениям Прутского мирного договора."},{"id":"5","label":"Буквой «Б» обозначены территории, утраченные Россией по результатам русско-шведской войны 1700-1721 гг."},{"id":"6","label":"Цифрой «2» на карте отмечен Смоленск."}],"answer":["3","4","6"],"hint":"Сопоставьте каждое утверждение с источником или схемой и с хронологией событий.","bodyHtml":"<p>Материал к заданию: <a href=\"https://cdn.studycats.ru/rwPJiUoeRizJ_%25D0%25B2%25D0%25BE%25D1%2581%25D1%2581%25D1%2582.jpg\" target=\"_blank\" rel=\"noopener noreferrer\">Открыть оригинал изображения 1</a></p><p>Если изображение не открывается, перейдите к следующему заданию: для ответа нужна схема из источника.</p>"}]}];for(const t of incoming){if(!window.EGE_TESTS.some(x=>x.id===t.id))window.EGE_TESTS.splice((()=>{const i=window.EGE_TESTS.findIndex(x=>x.id==="history-course-images-9"||x.id==="history-course-culture");return i<0?window.EGE_TESTS.length:i;})(),0,t);}Object.assign(window.EGE_VIDEO_LESSONS.byTest,{"history-course-nov11-1":[{"url":"https://rutube.ru/play/embed/66240c709f85bfb1503c4aa0048d138a/?p=-gWgO5jHlRu1LGzejPx76A","title":"Первые Романовы · Лекция 1"},{"url":"https://rutube.ru/play/embed/f03820127da7321597902d7ab54e6c5f/?p=z9AQ2b6H0XbL3sxZbL4OZA","title":"Первые Романовы · Лекция 2"}],"history-course-nov11-2":[{"url":"https://rutube.ru/play/embed/66240c709f85bfb1503c4aa0048d138a/?p=-gWgO5jHlRu1LGzejPx76A","title":"Первые Романовы · Лекция 1"},{"url":"https://rutube.ru/play/embed/f03820127da7321597902d7ab54e6c5f/?p=z9AQ2b6H0XbL3sxZbL4OZA","title":"Первые Романовы · Лекция 2"}],"history-course-nov11-3":[{"url":"https://rutube.ru/play/embed/685d6408862307553f4f16d01eef2bfe/?p=D5jDcX08gZ79wqOv3Qi4AQ","title":"Пётр I · Лекция 1"},{"url":"https://rutube.ru/play/embed/733bc9f7c12b53f854b8eeebfe178043/?p=D5Pm7KNYfrI-T_qTLpY33g","title":"Пётр I · Лекция 2"},{"url":"https://rutube.ru/play/embed/d4cbf009bb54d8ff33660b0b9c9bf0ac/?p=yehEulnPQEvDiG5RBn2X4g","title":"Пётр I · Лекция 3"}]});})();
